<div class="page-heading"><div><div class="eyebrow">WEBSITE SETTINGS</div><h1><?=e(App\Models\SettingFields::groups()[$group][0])?></h1><p>Keep the details consistent, everywhere on your website.</p></div></div><?php if($group==='integrations'):?><div class="notice">Email notifications use your hosting provider's PHP mail configuration. Set MAIL_ENABLED and MAIL_FROM in .env. Turnstile also requires TURNSTILE_SECRET in .env. Secrets are never displayed here.</div><?php endif?><?php if($group==='seo'):?><div class="notice">Search indexing starts disabled so you can review the recovered content before launch.</div><?php endif?><?php if($errors):?><div class="notice error" role="alert">Please correct the fields below.</div><?php endif?><form method="post" class="panel editor-form" data-unsaved><?=csrf_field()?><div class="editor-section"><div class="form-grid"><?php foreach($fields as $settingKey=>[$label,$type]):$key=str_replace('.','_',$settingKey);$field=['label'=>$label,'type'=>$type==='media'?'relation':($type==='mobile'?'select':($type==='color'?'text':($type==='analytics'||$type==='map'?'text':$type)))];if($type==='media')$field['table']='media_files';if($type==='mobile')$field['options']=['toggle'=>'Expandable menu','expanded'=>'Always expanded on mobile'];$record=[$key=>$values[$settingKey]];$fieldErrors=isset($errors[$settingKey])?[$key=>$errors[$settingKey]]:[];cms_view('admin/field',['key'=>$key,'field'=>$field,'record'=>$record,'errors'=>$fieldErrors]);endforeach?></div></div><div class="editor-actions"><a class="button secondary" href="<?=e(cms_url('/admin'))?>">Cancel</a><button class="button">Save website settings →</button></div></form>
